    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 2)]

    # Extend each row of the rectangle across the grid, stopping on the
    # side indicated by any marker on that row.
    for r in range(r0, r1 + 1):
        left_marker = any(rr == r and c < c0 for rr, c in markers)
        right_marker = any(rr == r and c > c1 for rr, c in markers)
        if not left_marker:
            for c in range(c0):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if not right_marker:
            for c in range(c1 + 1, w):
                if grid[r][c] == 0:
                    out[r][c] = 2

    # Extend vertically, leaving marker columns unfilled on the indicated end.
    blocked_above = {c for r, c in markers if r < r0 and c0 <= c <= c1}
    blocked_below = {c for r, c in markers if r > r1 and c0 <= c <= c1}
    for c in range(c0, c1 + 1):
        if c not in blocked_above:
            for r in range(r0):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if c not in blocked_below:
            for r in range(r1 + 1, h):
                if grid[r][c] == 0:
                    out[r][c] = 2

    return out
